package com.careerpilot.assessment;
import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="RUN_LIVE_ASSESSMENT_TEST",matches="true")
class LiveAssessmentIntegrationTest{
 private static final UUID ASSESSMENT=UUID.fromString("10000000-0000-0000-0000-000000000002");@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;
 @Test void verifiesLivePostgresQuestionBankAndAttemptSnapshot()throws Exception{long stamp=System.currentTimeMillis();String owner=register("live-assessment-owner-"+stamp+"@example.invalid"),other=register("live-assessment-other-"+stamp+"@example.invalid");String detail=mvc.perform(get("/api/v1/assessments/{id}",ASSESSMENT).header("Authorization",owner)).andExpect(status().isOk()).andExpect(jsonPath("$.assessment.totalQuestions").value(10)).andExpect(jsonPath("$.questions.length()").value(15)).andReturn().getResponse().getContentAsString();assertThat(detail).doesNotContain("correctOption").doesNotContain("isCorrect");JsonNode started=json.readTree(mvc.perform(post("/api/v1/assessments/{id}/attempts",ASSESSMENT).header("Authorization",owner)).andExpect(status().isCreated()).andExpect(jsonPath("$.questions.length()").value(10)).andReturn().getResponse().getContentAsString());String id=started.path("id").asText();List<String>selected=new ArrayList<>();started.path("questions").forEach(q->selected.add(q.path("id").asText()));assertThat(selected).hasSize(10).doesNotHaveDuplicates();String first=selected.get(0),second=selected.get(1),correct=jdbc.queryForObject("select option_key from assessment_options where question_id = ? and is_correct",String.class,UUID.fromString(first)),secondCorrect=jdbc.queryForObject("select option_key from assessment_options where question_id = ? and is_correct",String.class,UUID.fromString(second)),wrong=secondCorrect.equals("A")?"B":"A";String body=json.writeValueAsString(Map.of("answers",List.of(Map.of("questionId",first,"selectedOptionKey",correct),Map.of("questionId",second,"selectedOptionKey",wrong))));JsonNode result=json.readTree(mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.scorePercentage").value(10)).andExpect(jsonPath("$.correctAnswers").value(1)).andExpect(jsonPath("$.incorrectAnswers").value(1)).andExpect(jsonPath("$.unanswered").value(8)).andExpect(jsonPath("$.results.length()").value(10)).andReturn().getResponse().getContentAsString());mvc.perform(post("/api/v1/assessment-attempts/{id}/submit",id).header("Authorization",owner).contentType("application/json").content(body)).andExpect(status().isConflict());mvc.perform(get("/api/v1/assessment-attempts/{id}",id).header("Authorization",other)).andExpect(status().isNotFound());assertThat(jdbc.queryForObject("select count(*) from assessment_attempt_questions where attempt_id = ?",Integer.class,UUID.fromString(id))).isEqualTo(10);assertThat(jdbc.queryForObject("select count(*) from assessment_answers where attempt_id = ?",Integer.class,UUID.fromString(id))).isEqualTo(2);assertThat(jdbc.queryForObject("select count(*) from assessment_questions where assessment_id = ?",Integer.class,ASSESSMENT)).isGreaterThanOrEqualTo(15);assertThat(jdbc.queryForObject("select count(*) from flyway_schema_history where version = '9'",Integer.class)).isEqualTo(1);mvc.perform(get("/v3/api-docs")).andExpect(status().isOk());mvc.perform(get("/actuator/health")).andExpect(status().isOk());System.out.printf("LIVE_ASSESSMENT_V9 id=%s score=%d bank=15 selected=10 snapshot=PERSISTED flyway=V9 ownership=PROTECTED%n",id,result.path("scorePercentage").asInt());}
 private String register(String email)throws Exception{String body=json.writeValueAsString(Map.of("fullName","Live Assessment","email",email,"password","Password1","confirmPassword","Password1"));JsonNode response=json.readTree(mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString());return"Bearer "+response.path("accessToken").asText();}
}
